/**
 * How Star-flowered paulownia (`hana-kiri`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/hana-kiri";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Three pointed leaves meet at a round joint and spread below three stalks. The flowers are small stars, with five in the middle and three on each side.","ja":"先のとがった葉を丸い節の下に三枚広げ、上には花穂を三本立てます。星形の花を中央に五つ、左右に三つずつ置きます。"};

export default construction;
export { construction, description };
